checks.command:
$docPaths = @('AGENTS.md','docs/README.md','planning/README.md','docs/governance/repository-governance.md','docs/automation/codex-tracking-guide.md','docs/automation/project-automation-guide.md','docs/automation/task-start-planning.md','docs/automation/workflow-efficiency.md','docs/automation/planning-review-site.md','docs/automation/governance-automation-simplification.md','docs/governance/delivery-control-model.md')
$repoPath = (Get-Location).Path
$linkErrors = [Collections.Generic.List[string]]::new()
$linkCount = 0
foreach ($docPath in $docPaths) {
  $docText = Get-Content -Raw -LiteralPath $docPath
  foreach ($link in [regex]::Matches($docText, '\[[^\]]+\]\(([^)]+)\)')) {
    $target = $link.Groups[1].Value
    if ($target -match '^[a-z]+://') { continue }
    $linkCount++
    $parts = $target.Split('#',2)
    $resolvedTarget = [IO.Path]::GetFullPath((Join-Path (Split-Path (Join-Path $repoPath $docPath)) $parts[0]))
    if (-not $resolvedTarget.StartsWith($repoPath + [IO.Path]::DirectorySeparatorChar, [StringComparison]::OrdinalIgnoreCase)) { $linkErrors.Add("$docPath : off-repository target $target"); continue }
    if (-not (Test-Path -LiteralPath $resolvedTarget)) { $linkErrors.Add("$docPath : missing target $target"); continue }
    if ($parts.Count -eq 2) {
      if (-not $resolvedTarget.EndsWith('.md')) { $linkErrors.Add("$docPath : unchecked non-Markdown fragment $target"); continue }
      $headings = [regex]::Matches((Get-Content -Raw -LiteralPath $resolvedTarget), '(?m)^#{1,6} (.+)$') | ForEach-Object { $_.Groups[1].Value.Trim().ToLowerInvariant() -replace '[^\p{L}\p{Nd}\s_-]','' -replace '\s','-' }
      if ($parts[1] -notin $headings) { $linkErrors.Add("$docPath : missing fragment $target") }
    }
  }
}
[pscustomobject]@{documents=$docPaths.Count;localLinks=$linkCount;errors=@($linkErrors)} | ConvertTo-Json
if ($linkErrors.Count) { exit 1 }
